function getRecent(count: number): ThemeApplyTrace[] {
  const n = Math.max(0, Math.min(count, buffer.length));
  return buffer.slice(-n).reverse();
}
// 当 n === 0，buffer.slice(-0) 返回整个 buffer 的副本

invalidateEpoch(appId: AgentId): void {
  const byTarget = this.pools.get(appId);
  if (!byTarget) return;
  const now = Date.now();
  for (const [targetKey, entry] of byTarget) {
    if (entry.refCount > 0) {
      entry.retired = true;
      entry.retiredAt = now;
    } else {
      this.discard(appId, targetKey, entry);
    }
  }
}

